/* ===== Terminale ES · Thème 1 · 1.3 Le climat du futur · Activité 1.1 « Manipuler un modèle simple » : contenus, d'après la fiche du professeur ===== */
const PROBLEM = "Comment peut-on modéliser le système climatique ? Quelle évolution du climat d'ici la fin du XXIe siècle les modèles climatiques prédisent-ils ?";
const gap = `<span class="gap">………</span>`;
/* valeurs du modèle, calculées une fois (elles servent aux réponses et aux corrigés) */
const OFF = k => Object.assign({}, FULL, { [k]: false });
const V = { C07: val(0, "C", 2007), T07: val(0, "T", 2007), C0: val(0, "C"), C8: val(8, "C"), C16: val(16, "C"), T0: val(0, "T"), T8: val(8, "T"), T16: val(16, "T"), H0: val(0, "H"), H8: val(8, "H"), H16: val(16, "H"),
  C25: val(8, "C", 2025), T25: val(8, "T", 2025), Twv: val(8, "T", 2107, OFF("wv")), Talb: val(8, "T", 2107, OFF("alb")), Tcarb: val(8, "T", 2107, OFF("carb")), Ccarb: val(8, "C", 2107, OFF("carb")) };
V.d8 = V.T8 - V.T07; V.d16 = V.T16 - V.T07; V.rat = V.d16 / V.d8;
V.Es = [0, 0.5, 1, 1.5, 2, 2.5, 3].find(e => Math.abs(val(e, "C") - V.C07) <= 6); V.Ts = val(V.Es, "T");
const f1 = x => fmt(x, 1), f0 = x => fmt(x, 0);
const OBS = { C: 426, T: 15.1, A: 1.44, E: 11.5 };

