const BIL = [
  "Un <u>modèle climatique</u> est une représentation simplifiée du climat : il <u>met en équations</u> les mécanismes essentiels (cycle du carbone, effet de serre, inertie de l'océan, rétroactions) puis les <u>résout numériquement</u>, pas à pas, par ordinateur.",
  "On choisit des <u>paramètres d'entrée</u> (hypothèses : émissions futures, rétroactions prises en compte) ; le modèle calcule des <u>variables de sortie</u> (concentration en CO₂, température, niveau des mers).",
  `Résultats de mon simulateur de 2007 à 2107 : émissions nulles → le CO₂ diminue lentement, la température reste presque stable (≈ ${f1(V.T0)} °C), mais la mer monte encore (≈ +${f0(V.H0)} cm) ; comme aujourd'hui → ≈ ${f1(V.T8)} °C (+${f1(V.d8)} °C) ; deux fois plus → ≈ ${f1(V.T16)} °C (+${f1(V.d16)} °C). <u>Plus on émet de CO₂, plus le réchauffement est fort</u> : c'est une relation de cause à effet (effet de serre).`,
  `Pour stabiliser le CO₂, il faudrait émettre environ ${fmt(V.Es)} GtC par an, soit <u>diviser les émissions actuelles par 8</u> : les puits de carbone n'absorbent qu'une partie du CO₂.`,
  "Critique : <u>points forts</u> (lois physiques connues, calcul rapide, comparaison de scénarios, ordre de grandeur des observations retrouvé) ; <u>limites</u> (une seule valeur moyenne pour la Terre, uniquement le CO₂, émissions constantes, pas de régions, de saisons ni de pluies ; il sous-estime le réchauffement observé).",
  "Construire un modèle est <u>complexe</u> : nombreux compartiments en interaction (atmosphère, océan, glaces, êtres vivants), <u>rétroactions</u> amplificatrices (la vapeur d'eau surtout), échelles de temps très différentes, émissions futures inconnues (on fait des <u>scénarios</u>), et des millions de calculs. On évalue les modèles en les comparant aux <u>observations</u> et aux <u>paléoclimats</u> ; ensemble, ils donnent une <u>fourchette</u> d'évolution du climat au XXIe siècle."];
const bilanHTML = () => BIL.map(x => `<p>${nb(x)}</p>`).join("");
const PARA = ["met en équations les mécanismes essentiels (cycle du carbone, effet de serre, inertie de l'océan, rétroactions) et les résout pas à pas sur ordinateur.",
  `la température moyenne passe de ${f1(V.T07)} °C à environ ${f1(V.T0)} °C si les émissions sont nulles, ${f1(V.T8)} °C si elles restent comme aujourd'hui et ${f1(V.T16)} °C si elles doublent.`,
  "il repose sur des lois physiques et compare vite des scénarios, mais il ne calcule qu'une moyenne mondiale et ne tient compte que du CO₂.",
  "le climat dépend de nombreux compartiments en interaction, de rétroactions, d'échelles de temps différentes et d'émissions futures que l'on ne connaît pas."];
const LINK = ["Un modèle climatique…", "Avec mon simulateur, d'ici 2107…", "Ce modèle est utile mais limité :", "Construire un modèle est complexe car…"];
const taskMsg = (ok, txt) => ({ ok, msg: txt });
const T3 = () => { const a = [[0, "nulles"], [8, "comme aujourd'hui"], [16, "deux fois plus"]].map(([e, n]) => [hasSim(e), n]); return taskMsg(a.every(x => x[0]), a.map(x => `${tick(x[0])} ${x[1]}`).join(" · ") + " (100 ans, toutes les rétroactions)"); };
const TFB = () => { const a = [["111", "modèle complet"], ["011", "sans vapeur d'eau"], ["101", "sans glaces"], ["110", "sans puits de carbone"]].map(([m, n]) => [hasSim(8, m), n]); return taskMsg(a.every(x => x[0]), "« Comme aujourd'hui », 100 ans : " + a.map(x => `${tick(x[0])} ${x[1]}`).join(" · ")); };
const TST = () => { const s = stabSim(), n = otherSims().length; return taskMsg(!!s, s ? `Trouvé : avec ${fmt(s.E)} GtC/an, le CO₂ de 2107 reste à 6 ppm près celui de 2007.` : n ? `${n} essai(s) « Autre » : aucun ne stabilise encore le CO₂ (à 6 ppm près). Continue !` : "Aucun essai « Autre » sur 100 ans pour l'instant."); };
const T8 = () => taskMsg(hasSim(8), hasSim(8) ? "Simulation « Comme aujourd'hui » sur 100 ans : faite." : "Simulation « Comme aujourd'hui » sur 100 ans : pas encore lancée.");
const READ = "Pour lire une valeur : touche le graphique ou déplace le curseur « Lire une année » ; le tableau sous le graphique donne aussi les valeurs.";

